Функция ТаблицаКомпоновкиОпыта(Данные,Порог = Неопределено,ПоКлиенту = Ложь) Экспорт
    Схема = Новый СхемаКомпоновкиДанных;
    Источник = Схема.ИсточникиДанных.Добавить(); Источник.Имя = "Основной"; Источник.ТипИсточникаДанных = "Local";
    Набор = Схема.НаборыДанных.Добавить(Тип("НаборДанныхЗапросСхемыКомпоновкиДанных")); Набор.Имя = "Заявки"; Набор.ИсточникДанных = "Основной";
    Набор.Запрос = "ВЫБРАТЬ З.Ссылка КАК Ссылка, З.Клиент КАК Клиент, З.ДлительностьМинут КАК Минуты ИЗ Документ.ЗаявкаУслуги КАК З";
    Для Каждого Имя Из СтрРазделить("Ссылка,Клиент,Минуты",",") Цикл
        Поле = Набор.Поля.Добавить(Тип("ПолеНабораДанныхСхемыКомпоновкиДанных")); Поле.ПутьКДанным = Имя; Поле.Поле = Имя; Поле.Заголовок = Имя;
    КонецЦикла;
    Настройки = Новый НастройкиКомпоновкиДанных;
    ПоляВывода = ?(ПоКлиенту,"Клиент,Минуты","Ссылка,Минуты");
    Для Каждого Имя Из СтрРазделить(ПоляВывода,",") Цикл
        Выбор = Настройки.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных")); Выбор.Поле = Новый ПолеКомпоновкиДанных(Имя); Выбор.Использование = Истина;
    КонецЦикла;
    Группа = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных")); Группа.Использование = Истина;
    Группа.Выбор.Элементы.Добавить(Тип("АвтоВыбранноеПолеКомпоновкиДанных"));
    Если ПоКлиенту Тогда
        Итог = Схема.TotalFields.Add(); Итог.DataPath = "Минуты"; Итог.Expression = "Сумма(Минуты)";
        ПолеГруппы = Группа.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных")); ПолеГруппы.Поле = Новый ПолеКомпоновкиДанных("Клиент");
    КонецЕсли;
    Отбор = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных")); Отбор.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Клиент"); Отбор.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно; Отбор.ПравоеЗначение = Данные.Клиент; Отбор.Использование = Истина;
    Если Порог <> Неопределено Тогда
        Отбор = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных")); Отбор.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Минуты"); Отбор.ВидСравнения = ВидСравненияКомпоновкиДанных.Больше; Отбор.ПравоеЗначение = Порог; Отбор.Использование = Истина;
    КонецЕсли;
    Компоновщик = Новый КомпоновщикМакетаКомпоновкиДанных;
    Макет = Компоновщик.Выполнить(Схема,Настройки,,,Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));
    Процессор = Новый ПроцессорКомпоновкиДанных; Процессор.Инициализировать(Макет);
    Вывод = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВКоллекциюЗначений;
    Возврат Вывод.Вывести(Процессор);
КонецФункции

Функция ОпытДвухКороткихРабот() Экспорт
    Д = НовыйНаборРегистров(25,25);
    Детали = ТаблицаКомпоновкиОпыта(Д,40);
    Группы = ТаблицаКомпоновкиОпыта(Д,Неопределено,Истина);
    Прошло40 = 0; Минут40 = 0; Прошло50 = 0;
    Для Каждого СтрокаГруппы Из Группы Цикл
        Если СтрокаГруппы.Клиент <> Д.Клиент Тогда Продолжить; КонецЕсли;
        Если СтрокаГруппы.Минуты > 40 Тогда
            Прошло40 = Прошло40 + 1; Минут40 = Минут40 + СтрокаГруппы.Минуты;
        КонецЕсли;
        Если СтрокаГруппы.Минуты > 50 Тогда Прошло50 = Прошло50 + 1; КонецЕсли;
    КонецЦикла;
    Возврат Новый Структура("СтрокДеталей,МинутДеталей,Групп,МинутГруппы,ГруппНаГранице",Детали.Количество(),Детали.Итог("Минуты"),Прошло40,Минут40,Прошло50);
КонецФункции

